        "x": #"<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" d="M6 18 18 6M6 6l12 12"/></svg>"#,
    ]

    private static var cache: [String: NSImage] = [:]

    static func image(_ name: String, size: CGFloat) -> NSImage {
        let key = "\(name)-\(size)"
        if let cached = cache[key] { return cached }
        let side = ceil(size * 1.15)
        let source = svgs[name].flatMap { NSImage(data: Data($0.utf8)) }
        if source == nil { NSLog("Hourfox: нет иконки \(name)") }
        let image = NSImage(size: NSSize(width: side, height: side), flipped: false) { rect in
            source?.draw(in: rect)
            return true
        }
        image.isTemplate = true
        cache[key] = image
        return image
    }

    /// Какие иконки не прочитались: проверка в тестах.
    static var missing: [String] {
        svgs.filter { NSImage(data: Data($0.value.utf8)) == nil }.keys.sorted()
    }
}

/// Значок настройки, как в Системных настройках macOS: белая иконка на одинаковой плашке.
struct SettingIcon: View {
    let name: String
    var side: CGFloat = 24

    var body: some View {
        Image(icon: name, size: (side * 0.6).rounded())
            .foregroundStyle(.white)
            .frame(width: side, height: side)
            .background(RoundedRectangle(cornerRadius: side * 0.24, style: .continuous).fill(Color.accentColor))
    }
}

extension Image {
    init(icon name: String, size: CGFloat = 15) {
        self.init(nsImage: AppIcon.image(name, size: size))
    }
}

extension Label where Title == Text, Icon == Image {
    init(_ title: LocalizedStringKey, icon name: String) {
        self.init { Text(title) } icon: { Image(icon: name) }
    }

    @_disfavoredOverload
    init<S: StringProtocol>(_ title: S, icon name: String) {
        self.init { Text(title) } icon: { Image(icon: name) }
    }
}
